fn fixed_odd(m:u128)->([i16;11],u8,u64){assert!(m<1u128<<126);let mut d=[0i16;11];if m==0{return(d,0,0);}let skew=u8::from(m&1==0);let mut k=m+skew as u128;for x in&mut d{if k==0{break;}assert_eq!(k&1,1);let residue=(k&4095)as i16;let higher=k>>12;let negative=higher>0&&higher&1==0;*x=residue-if negative{4096}else{0};k=if negative{higher+1}else{higher};}assert_eq!(k,0);let mut collapses=0;for i in 1..d.len(){if(d[i]==1&&d[i-1]<0)||(d[i]==-1&&d[i-1]>0){let delta=if d[i]>0{4096}else{-4096};d[i-1]+=delta;d[i]=0;collapses+=1;}}(d,skew,collapses)}
