let mut rows=Vec::new();let mut first=0;let mut merges=0;let mut fold=0;let mut odd_doublings=0;for w in 0..11{let occupied=counts[w].iter().map(|p|p.iter().filter(|&&v|v>0).count()as u64).collect::<Vec<_>>();let overlap=(0..2048).filter(|&b|counts[w][0][b]>0&&counts[w][1][b]>0).count()as u64;let max=(0..2048).rev().find(|&b|counts[w][0][b]>0||counts[w][1][b]>0).map(|b|b+1).unwrap_or(0)as u64;let f=2*max.saturating_sub(1);let doubling=u64::from(max>1);first+=occupied.iter().sum::<u64>();merges+=overlap;fold+=f;odd_doublings+=doubling;rows.push(json!({"position":w,"arrivals":arrivals[w],"occupied_per_part":occupied,"overlap_slots":overlap,"last_used_slot_plus1":max,"dense_weighted_fold_model_adds":f,"odd_weight_doublings":doubling}));}
